from collections import Counter

def _runs(vals, bg):
    runs=[]; i=0
    while i<len(vals):
        if vals[i]==bg:
            i+=1; continue
        j=i+1
        while j<len(vals) and vals[j]==vals[i]:
            j+=1
        if j-i>=2:
            runs.append((i,j,vals[i]))
        i=j
    return runs

